def graded(assertion: Assertion, after: Any, **kwargs: Any) -> grading.Outcome:
    case = use_case(assertion, guards=kwargs.pop("guards", None), maxdrop=kwargs.pop("maxdrop", 0))
    evidence = grading.evidence_for(case, BEFORE, after, **kwargs)
    return grading.grade(case, evidence)[0]


def test_every_kind_the_catalog_allows_has_an_implementation() -> None:
    """The registry is a contract in both directions: T2.5 answers for every name in it."""
    assert set(grading.CHECKS) == set(KINDS)


def test_every_field_the_27_use_cases_name_is_one_the_grader_can_read() -> None:
    """`validate.py` checks kinds and required parameters; nobody checked the field *names*.

    A `fields: {sur_name: …}` would load, validate and grade — against a reader that does not
    exist. This is the last place the catalog and the grader could disagree in silence.
    """
    known = set(checks_record.PERSON_FIELDS) | set(checks_record.SOURCE_FIELDS)
    used = {
        str(field)
        for case in load_all().values()
        for assertion in case.assertions
        for field in (assertion.params.get("fields") or {})
    }

    assert used <= known, f"the catalog names {sorted(used - known)}, which nothing can read"


