def _plus(record: dict[str, Any]) -> Any:
    return make.state(
        people=(*BEFORE.of("people"), record),
        families=BEFORE.of("families"),
        sources=BEFORE.of("sources"),
        notes=BEFORE.of("notes"),
        tags=BEFORE.of("tags"),
    )


def _replacing(record: dict[str, Any]) -> Any:
    namespaces = {}
    for namespace in ("people", "families", "sources", "notes", "tags"):
        namespaces[namespace] = tuple(
            record if existing["handle"] == record["handle"] else existing
            for existing in BEFORE.of(namespace)
        )
    return make.state(**namespaces)


def _without_family() -> Any:
    """The household gone — and both spouses' `family_list` gone with it, as the server does."""
    return make.state(
        people=tuple(
            {**person, "family_list": []} if person["family_list"] else person
            for person in BEFORE.of("people")
        ),
        families=(),
        sources=BEFORE.of("sources"),
        notes=BEFORE.of("notes"),
        tags=BEFORE.of("tags"),
    )
